function seedEvents(){
  return REAL_EVENTS.map(e => Object.assign({}, e, {
    createdAt: T.addDays(T.todayKey(), -60),
    updatedAt: T.addDays(T.todayKey(), -20),
    createdBy: 'u2', updatedBy: 'u2'
  }));
}

