/* -------------------------------------------------------------- STORE ---- */
const STORAGE_KEY = 'pbis-central-calendar-v2';

const Store = {
  state:{
    events:[], submissions:[], auditLog:[],
    campuses:CAMPUSES.slice(), yearGroups:YEAR_GROUPS.slice(), categories:CATEGORIES.slice(),
    locations:LOCATIONS.slice(), academicYears:ACADEMIC_YEARS.slice(), terms:TERMS.slice(),
    currentUserId:'u2',
    session:{ signedIn:false, since:null },
    prefs:{ theme:'light', motion:'on', onboarded:false, campusId:null, yearGroupId:null, audienceId:null, categoryIds:[], subscriptions:[] },
    ui:{ view:'month', cursor:null, ayId:'ay2627', filters:{campusIds:[],yearGroupIds:[],categoryIds:[],audienceIds:[],statuses:[],q:''} }
  },
  listeners:new Set(),
  _undo:null,

  init(){
    const saved = safeParse(localStorage.getItem(STORAGE_KEY));
    this.state.events = seedEvents();
    this.state.submissions = seedSubmissions();
    this.state.auditLog = seedAudit(this.state.events);
    this.state.ui.cursor = T.todayKey();
    if(saved && saved.prefs) Object.assign(this.state.prefs, saved.prefs);
    if(saved && saved.session) Object.assign(this.state.session, saved.session);
    if(saved && saved.currentUserId) this.state.currentUserId = saved.currentUserId;
    if(saved){
      // Edits to seeded events are replayed over the canonical seed…
      (saved.overrides||[]).forEach(o=>{
        const i = this.state.events.findIndex(x=>x.id===o.id);
        if(i>-1) this.state.events[i] = Object.assign(this.state.events[i], o);
      });
      // …then the user's own events are appended, never duplicated.
      const known = new Set(this.state.events.map(e=>e.id));
      (saved.userEvents||[]).forEach(e=>{ if(!known.has(e.id)){ this.state.events.push(e); known.add(e.id); } });
    }
    applyTheme(this.state.prefs.theme);
    applyMotion(this.state.prefs.motion);
  },
  persist(){
    try{
      // Seeded events are regenerated from code on every load, so only the
      // user's own events and their edits to seeded ones are stored.
      const userEvents = this.state.events.filter(e=>!e.seeded);
      const overrides  = this.state.events.filter(e=>e.seeded && e.modified);
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        prefs:this.state.prefs, userEvents, overrides,
        session:this.state.session, currentUserId:this.state.currentUserId
      }));
    }catch(err){ /* storage may be unavailable — the app still works in-session */ }
  },
  subscribe(fn){ this.listeners.add(fn); return ()=>this.listeners.delete(fn); },
  emit(){ this.listeners.forEach(fn=>fn(this.state)); },
  set(patch){ Object.assign(this.state, patch); this.emit(); },
  setPrefs(patch){ Object.assign(this.state.prefs, patch); this.persist(); this.emit(); },
  setUI(patch){ Object.assign(this.state.ui, patch); this.emit(); },
  setFilters(patch){ Object.assign(this.state.ui.filters, patch); this.emit(); },

  GUEST:{id:'guest', name:'Guest', email:'', role:'public', campusId:null, initials:'G'},
  user(){
    if(!this.state.session.signedIn) return this.GUEST;
    return byId(USERS, this.state.currentUserId) || USERS[0];
  },
  signIn(userId){
    this.state.currentUserId = userId;
    this.state.session = {signedIn:true, since:new Date().toISOString()};
    this.audit('signed in', userId, byId(USERS,userId).name);
    this.persist(); this.emit();
  },
  signOut(){
    this.state.session = {signedIn:false, since:null};
    this.persist(); this.emit();
  },
  role(){ return ROLES[this.user().role]; },
  can(action){
    const r = this.user().role;
    const M = {
      view:['super','caladmin','campusadmin','teacher','parent','student','public'],
      submit:['super','caladmin','campusadmin','teacher'],
      create:['super','caladmin','campusadmin'],
      edit:['super','caladmin','campusadmin'],
      publish:['super','caladmin','campusadmin'],
      approve:['super','caladmin'],
      import:['super','caladmin'],
      manageTaxonomy:['super','caladmin'],
      manageUsers:['super'],
      viewAudit:['super','caladmin'],
      rollover:['super','caladmin']
    };
    return (M[action]||[]).includes(r);
  },
  scopedCampus(){ const u=this.user(); return u.role==='campusadmin' ? u.campusId : null; },

  /* --- mutations, all audited, all undoable --- */
  addEvent(ev, silent){
    ev.id = ev.id || uid();
    ev.seeded = false;
    ev.slug = ev.slug || slugify(ev.title)+'-'+ev.date.slice(2,7).replace('-','');
    ev.createdAt = T.todayKey(); ev.updatedAt = T.todayKey();
    ev.createdBy = this.state.currentUserId; ev.updatedBy = this.state.currentUserId;
    this.state.events.push(ev);
    this.audit('created', ev.id, ev.title);
    if(!silent) this._undo = {label:`Created “${ev.title}”`, fn:()=>{ this.state.events = this.state.events.filter(e=>e.id!==ev.id); this.persist(); this.emit(); }};
    this.persist(); this.emit(); return ev;
  },
  updateEvent(id, patch, action){
    const i = this.state.events.findIndex(e=>e.id===id); if(i<0) return null;
    const before = JSON.parse(JSON.stringify(this.state.events[i]));
    Object.assign(this.state.events[i], patch, {updatedAt:T.todayKey(), updatedBy:this.state.currentUserId, modified:true});
    this.audit(action||'updated', id, this.state.events[i].title);
    this._undo = {label:`Updated “${before.title}”`, fn:()=>{ const j=this.state.events.findIndex(e=>e.id===id); if(j>-1) this.state.events[j]=before; this.persist(); this.emit(); }};
    this.persist(); this.emit(); return this.state.events[i];
  },
  deleteEvent(id){
    const i = this.state.events.findIndex(e=>e.id===id); if(i<0) return;
    const before = this.state.events[i];
    this.state.events[i] = Object.assign({}, before, {status:'archived', deletedAt:T.todayKey(), modified:true});
    this.audit('archived', id, before.title);
    this._undo = {label:`Archived “${before.title}”`, fn:()=>{ const j=this.state.events.findIndex(e=>e.id===id); if(j>-1) this.state.events[j]=before; this.persist(); this.emit(); }};
    this.persist(); this.emit();
  },
  bulk(ids, patch, label){
    const before = ids.map(id=>JSON.parse(JSON.stringify(this.state.events.find(e=>e.id===id))));
    ids.forEach(id=>{ const i=this.state.events.findIndex(e=>e.id===id); if(i>-1){ Object.assign(this.state.events[i], patch, {updatedAt:T.todayKey(),updatedBy:this.state.currentUserId,modified:true}); }});
    this.audit('updated', ids[0], `${ids.length} events — ${label}`);
    this._undo = {label:`${label} (${ids.length} events)`, fn:()=>{ before.forEach(b=>{ const i=this.state.events.findIndex(e=>e.id===b.id); if(i>-1) this.state.events[i]=b; }); this.persist(); this.emit(); }};
    this.persist(); this.emit();
  },
  audit(action, entityId, title){
    this.state.auditLog.unshift({
      id:uid('a'), action, entityId, title,
      userId:this.state.currentUserId, at:new Date().toISOString(), date:T.todayKey()
    });
    if(this.state.auditLog.length>400) this.state.auditLog.length=400;
  },
  undo(){ if(this._undo){ const u=this._undo; this._undo=null; u.fn(); return u.label; } return null; },
  reset(){ try{localStorage.removeItem(STORAGE_KEY);}catch(e){} location.reload(); }
};
PBIS.Store = Store;

function safeParse(s){ try{ return JSON.parse(s); }catch(e){ return null; } }

function seedAudit(events){
  const log=[]; const acts=['created','updated','published','imported','approved'];
  const now = Date.now();
  events.slice(0,26).forEach((e,i)=>{
    log.push({id:uid('a'), action:acts[i%acts.length], entityId:e.id, title:e.title,
      userId:USERS[(i%5)].id, at:new Date(now - (i+1)*3.4*3600*1000).toISOString(), date:T.addDays(T.todayKey(),-Math.floor(i/3))});
  });
  return log;
}

function applyTheme(theme){
  document.documentElement.setAttribute('data-theme', theme==='dark'?'dark':'light');
}
function applyMotion(m){
  document.documentElement.setAttribute('data-motion', m==='off'?'off':'on');
}
PBIS.applyTheme=applyTheme; PBIS.applyMotion=applyMotion;

